/**
 * Figma Plan の人間確認用 Markdown（SPEC §56: docs/figma-implementation-plan.md）。
 * Plan Must Explain Why（§59）: 全判断に reason を出す。
 */
import type { FigmaPlan } from "./plan-types.js";

export function renderFigmaPlanMarkdown(plan: FigmaPlan): string {
  const lines: string[] = [
    "# Figma Implementation Plan",
    "",
    `- source: Figma file \`${plan.source.file_key}\` (version ${plan.source.figma_version})`,
    `- manifest fingerprint: \`${plan.manifest_fingerprint.slice(0, 16)}…\``,
    "- generated by `agentcms figma plan`（決定論・AI 判断なし）。**apply 前に REVIEW / UNKNOWN 項目を人が確認すること**",
    "",
    "## Screens",
    "",
    "| screen | route | breakpoints | confidence | 判断理由 |",
    "| --- | --- | --- | --- | --- |",
  ];
  for (const s of plan.screens) {
    lines.push(
      `| ${s.screen_id} | \`${s.route}\` | ${s.breakpoints.map((b) => `${b.breakpoint}(${b.width})`).join(" / ")} | ${s.confidence} | ${escapeCell(`${s.reason}。${s.responsive_note}`)} |`,
    );
  }
  lines.push("", "## Components（Existing Component First）", "");
  lines.push(
    "| component | action | target | confidence | 判断理由 |",
    "| --- | --- | --- | --- | --- |",
  );
  for (const c of plan.components) {
    lines.push(
      `| ${c.component_id} | ${c.action} | ${c.existing_target ?? c.target ?? "—"} | ${c.confidence} | ${escapeCell(c.reason)} |`,
    );
  }
  lines.push("", "## Design Tokens", "");
  lines.push(
    "| token | value | source | status | 判断理由 |",
    "| --- | --- | --- | --- | --- |",
  );
  for (const t of plan.tokens) {
    lines.push(
      `| ${t.name} | \`${t.value}\` | ${t.source} | ${t.status} | ${escapeCell(t.reason)} |`,
    );
  }
  lines.push("", "## CMS", "");
  lines.push(
    "| candidate | action | module | items | confidence | 判断理由 |",
    "| --- | --- | --- | --- | --- | --- |",
  );
  for (const c of plan.cms) {
    lines.push(
      `| ${c.candidate_id} | ${c.action} | ${c.module ?? "—"} | ${c.seed_items} | ${c.confidence} | ${escapeCell(c.reason)} |`,
    );
  }
  lines.push("", "## Assets", "");
  lines.push(
    "| asset | classification | action | target | 判断理由 |",
    "| --- | --- | --- | --- | --- |",
  );
  for (const a of plan.assets) {
    lines.push(
      `| ${a.asset_id} | ${a.classification} | ${a.action} | ${a.target ?? "—"} | ${escapeCell(a.reason)} |`,
    );
  }
  lines.push("", "## Fonts", "");
  lines.push(
    "| family | weights | availability | action | 判断理由 |",
    "| --- | --- | --- | --- | --- |",
  );
  for (const f of plan.fonts) {
    lines.push(
      `| ${f.family} | ${f.weights.join(", ")} | ${f.availability} | ${f.action} | ${escapeCell(f.reason)} |`,
    );
  }
  if (plan.schema_overrides.length > 0) {
    lines.push("", "## Project Scope Schema Overrides（ADR-0010 Rev.1）", "");
    for (const o of plan.schema_overrides) {
      lines.push(
        `- \`${o.schema}.${o.field}\` ← \`${JSON.stringify(o.patch)}\` — ${o.reason}`,
      );
    }
  }
  if (plan.uncertainties.length > 0) {
    lines.push("", "## 要確認（REVIEW / UNKNOWN）", "");
    for (const u of plan.uncertainties) {
      lines.push(`- **${u.area}**: ${u.message}`);
    }
  }
  if (plan.warnings.length > 0) {
    lines.push("", "## Warnings", "");
    for (const w of plan.warnings) {
      lines.push(`- [${w.code}] ${w.message}`);
    }
  }
  lines.push(
    "",
    "---",
    "",
    "承認後: `agentcms figma apply`（Figma へは書き込まない — Local Project のみ変更）",
    "",
  );
  return lines.join("\n");
}

function escapeCell(text: string): string {
  return text.replaceAll("|", "\\|").replaceAll("\n", " ");
}
